body:
Subject: RE: [ILUG] problème de pthreads Linux

> Utilisez-vous pthread_join(somethread,0);
> Lorsque vous fermez votre fil de discussion instancié créé à partir de
> pthread_t*quelquethread ?

Quelque chose comme ça pourrait vous aider.... 

Classe la{
 Public :
	pthread_t*thread;
	void thread_me (int num)
	} ;

la*lala;

liste de structures typedef
{
 loi*w;
 struct liste*suivant ;
}list_struct;

list_struct*head;

void thread_me(int num);
void add_to_list(la*o);
void delete_from_list();

int principal(int argc,char**argv)
{
entier a=1 ;

 lala=nouveau la;
 fil= nouveau pthread_t;
 add_to_list(lala);
 pthread_create(thread,0,&lala.thread_me,&a);

 fil= nouveau pthread_t;
 add_to_list(lala);
 pthread_create(thread,0,&lala.thread_me,&a);

delete_from_linked_list();
renvoie 0 ;
} ;

void lala::thread_me(int num)
{
 printf("lalala");
 pthread_join((*this)->thread,0);
retour;
} ;

annuler add_to_list(la*o)
{
 list_struct statique*a ;
 a=nouvelle list_struct ;
 a->w=o ;
 a->suivant=tête ;
 tête = un ;
retour;
} ;

annuler delete_from_linked_list()
{
 list_struct*a;

 pendant que(tête!=NULL)
	{
	 a = tête ;
	 head=head->suivant ;
 	 supprimer un ;
	} ;
 retour;
} ;

-- 
